var gcdSum = function(nums) {
    const n = nums.length;
    const prefixGcd = Array(n);
    let max = -Infinity;

    for (let i = 0; i < n; i++) {
        max = Math.max(max, nums[i]);
        prefixGcd[i] = gcd(nums[i], max);
    }

    let arr = prefixGcd.slice().sort((a, b) => a - b);
    const halfLen = Math.floor(arr.length / 2);
    let res = 0;

    for (let i = 0; i < halfLen; i++) {
        res += gcd(arr[arr.length - 1 - i], arr[i]);
    }

    return res;
};

const gcd = (a, b) => {
    while (b !== 0) {
        [a, b] = [b, a % b];
    }
    return a;
};

